// rehash.go v3 — backfill repair for PR #520.
// Zero identifier bytes appear in this file or any invocation: every
// scrub pattern is DERIVED at runtime from the committed identity
// record (.punt-labs/ethos/identities/, the product's own public data),
// including reconstructable variants (regex-escaped dots, quoted
// string-concatenation fragments) that earlier rounds re-leaked via
// sealed audit captures of the fix commands themselves.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

const previewLimit = 200

var pairs [][2]string
var scanPatterns []string

func fragQuoted(s string) []string {
	// quoted-concatenation forms as they appear in recorded commands:
	// "ab" + "cd" split at every boundary that earlier tooling used —
	// generate all two-part splits to be safe.
	var out []string
	for i := 2; i < len(s)-2; i++ {
		out = append(out, `"`+s[:i]+`" + "`+s[i:]+`"`)
	}
	return out
}

func initPatterns() error {
	b, err := os.ReadFile(".punt-labs/ethos/identities/jfreeman.yaml")
	if err != nil {
		return err
	}
	var email, handle string
	for _, ln := range strings.Split(string(b), "\n") {
		ln = strings.TrimSpace(ln)
		if v, ok := strings.CutPrefix(ln, "email:"); ok {
			email = strings.TrimSpace(v)
		}
		if v, ok := strings.CutPrefix(ln, "handle:"); ok {
			handle = strings.TrimSpace(v)
		}
	}
	if email == "" || handle == "" {
		return fmt.Errorf("identity fields not found")
	}
	tokE := "[RED" + "ACTED:email]"
	tokH := "[RED" + "ACTED:home-path]"
	// second known personal address: local part from handle's initials
	// convention is not derivable — read it from the git config instead.
	second := ""
	if gb, err := os.ReadFile(os.Getenv("HOME") + "/.punt-labs/git-identity.env"); err == nil {
		for _, ln := range strings.Split(string(gb), "\n") {
			if i := strings.Index(ln, "@"); i > 0 && strings.Contains(ln, "EMAIL") {
				f := strings.Trim(strings.SplitN(ln, "=", 2)[1], `"' `)
				if f != email {
					second = f
				}
			}
		}
	}
	addrs := []string{email}
	if second != "" {
		addrs = append(addrs, second)
	}
	for _, a := range addrs {
		pairs = append(pairs, [2]string{a, tokE})
		esc := strings.ReplaceAll(a, ".", `\.`)
		pairs = append(pairs, [2]string{esc, tokE})
		for _, f := range fragQuoted(a) {
			pairs = append(pairs, [2]string{f, `"` + tokE + `"`})
		}
		scanPatterns = append(scanPatterns, a, esc)
		scanPatterns = append(scanPatterns, fragQuoted(a)...)
	}
	pairs = append(pairs,
		[2]string{"-home-" + handle + "-", "-home-user-"},
		[2]string{"-Users-" + handle + "-", "-Users-user-"},
		[2]string{"/home/" + handle + "/", tokH},
		[2]string{"/Users/" + handle + "/", tokH},
		[2]string{"/home/" + handle, tokH},
		[2]string{"/Users/" + handle, tokH},
	)
	scanPatterns = append(scanPatterns,
		"-home-"+handle, "-Users-"+handle, "/home/"+handle, "/Users/"+handle)
	return nil
}

func scrubText(s string) string {
	for _, p := range pairs {
		s = strings.ReplaceAll(s, p[0], p[1])
	}
	return s
}

func needsScrub(s string) bool {
	for _, p := range scanPatterns {
		if strings.Contains(s, p) {
			return true
		}
	}
	return false
}

func scrubValue(v any) (any, bool) {
	switch t := v.(type) {
	case string:
		n := scrubText(t)
		return n, n != t
	case map[string]any:
		ch := false
		for k, val := range t {
			nv, c := scrubValue(val)
			t[k] = nv
			ch = ch || c
		}
		return t, ch
	case []any:
		ch := false
		for i, val := range t {
			nv, c := scrubValue(val)
			t[i] = nv
			ch = ch || c
		}
		return t, ch
	default:
		return v, false
	}
}

func processLine(line string) (string, bool, error) {
	if !needsScrub(line) {
		return line, false, nil
	}
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	var obj map[string]any
	if err := dec.Decode(&obj); err != nil {
		return line, false, fmt.Errorf("parse: %w", err)
	}
	oldHash, _ := obj["tool_input_hash"].(string)
	_, hadPrev := obj["tool_input_preview"].(string)
	_, hasTI := obj["tool_input"]
	if !hasTI {
		out := scrubText(line)
		return out, out != line, nil
	}
	ti, _ := scrubValue(obj["tool_input"])
	data, err := json.Marshal(ti)
	if err != nil {
		return line, false, err
	}
	sum := sha256.Sum256(data)
	newHash := hex.EncodeToString(sum[:])
	s := string(data)
	newPrev := s
	if len(s) > previewLimit {
		newPrev = s[:previewLimit] + "..."
	}
	out := scrubText(line)
	if oldHash != "" && oldHash != newHash {
		if strings.Count(out, oldHash) != 1 {
			return line, false, fmt.Errorf("hash count %d", strings.Count(out, oldHash))
		}
		out = strings.Replace(out, oldHash, newHash, 1)
	}
	if hadPrev {
		newPrevRaw, _ := json.Marshal(newPrev)
		key := `"tool_input_preview":`
		i := strings.Index(out, key+`"`)
		if i < 0 {
			return line, false, fmt.Errorf("preview key missing")
		}
		j := i + len(key)
		k := j + 1
		for k < len(out) {
			if out[k] == '\\' {
				k += 2
				continue
			}
			if out[k] == '"' {
				break
			}
			k++
		}
		out = out[:j] + string(newPrevRaw) + out[k+1:]
	}
	if !strings.Contains(out, `"redacted":true`) {
		if !strings.HasSuffix(out, "}") {
			return line, false, fmt.Errorf("no closing brace")
		}
		out = out[:len(out)-1] + `,"redacted":true}`
	}
	vdec := json.NewDecoder(strings.NewReader(out))
	vdec.UseNumber()
	var vo map[string]any
	if err := vdec.Decode(&vo); err != nil {
		return line, false, fmt.Errorf("verify parse: %w", err)
	}
	vdata, err := json.Marshal(vo["tool_input"])
	if err != nil {
		return line, false, err
	}
	vsum := sha256.Sum256(vdata)
	if got, _ := vo["tool_input_hash"].(string); got != hex.EncodeToString(vsum[:]) {
		return line, false, fmt.Errorf("verify hash mismatch")
	}
	if needsScrub(out) {
		return line, false, fmt.Errorf("remnant survives")
	}
	return out, out != line, nil
}

func main() {
	if err := initPatterns(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	mode := ""
	raw := false
	for _, arg := range os.Args[1:] {
		switch arg {
		case "--scan":
			mode = "scan"
			continue
		case "--raw":
			raw = true
			continue
		}
		b, err := os.ReadFile(arg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
		n := 0
		if mode == "scan" {
			for _, line := range lines {
				if needsScrub(line) {
					n++
				}
			}
			if n > 0 {
				fmt.Printf("REMNANTS %d %s\n", n, arg)
			}
			continue
		}
		for i, line := range lines {
			if line == "" {
				continue
			}
			if raw {
				nl := scrubText(line)
				if nl != line {
					lines[i], n = nl, n+1
				}
				continue
			}
			nl, ch, err := processLine(line)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s:%d: %v\n", arg, i+1, err)
				os.Exit(1)
			}
			if ch {
				lines[i], n = nl, n+1
			}
		}
		if n > 0 {
			if err := os.WriteFile(arg, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
		}
		fmt.Printf("%s: %d updated (raw=%v)\n", arg, n, raw)
		raw = false
	}
	if mode == "scan" {
		fmt.Println("scan done")
	}
}

tool_input.command:
python3 - <<'EOF'
import pathlib
p = pathlib.Path("<repo>/.tmp/rehash.go")
t = p.read_text()
anchor = '''	scanPatterns = append(scanPatterns,
		"-home-"+handle, "-Users-"+handle, "/home/"+handle, "/Users/"+handle)
	return nil'''
add = '''	scanPatterns = append(scanPatterns,
		"-home-"+handle, "-Users-"+handle, "/home/"+handle, "/Users/"+handle)
	// JSON-escaped renderings: patterns as they appear inside raw JSONL
	// string values (escaped quotes/backslashes), so the pre-decode gate
	// and the raw-text scrub both see them.
	addEsc := func(list [][2]string) [][2]string {
		var out [][2]string
		for _, pr := range list {
			out = append(out, pr)
			eb, _ := json.Marshal(pr[0])
			rb, _ := json.Marshal(pr[1])
			e := string(eb[1 : len(eb)-1])
			r := string(rb[1 : len(rb)-1])
			if e != pr[0] {
				out = append(out, [2]string{e, r})
			}
		}
		return out
	}
	pairs = addEsc(pairs)
	var se []string
	for _, s := range scanPatterns {
		se = append(se, s)
		eb, _ := json.Marshal(s)
		if e := string(eb[1 : len(eb)-1]); e != s {
			se = append(se, e)
		}
	}
	scanPatterns = se
	return nil'''
assert anchor in t
t = t.replace(anchor, add, 1)
p.write_text(t)
print("escaped variants added")
EOF
